contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}();

        uint balBefore = address(c).balance;
        uint creditBefore = c.credit(address(this));
        require(depositAmount == creditBefore);

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint creditAfter = c.credit(address(this));
        uint balAfter = address(c).balance;

        if (!reverted) {
            assert(creditAfter == 0 && balAfter == balBefore - creditBefore);
        } else {
            assert(creditAfter == creditBefore && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

