contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        uint balBeforeDeposit = address(c).balance;
        c.deposit{value: depositAmount}();
        uint balAfterDeposit = address(c).balance;

        bool userCreditNonNegative = c.credit(address(this)) >= 0;

        uint userCreditBeforeWithdraw = c.credit(address(this));
        uint balBeforeWithdraw = address(c).balance;

        bool withdrew = false;
        if (withdrawAmount <= userCreditBeforeWithdraw) {
            c.withdrawAll();
            withdrew = true;
        }

        uint balAfterWithdraw = address(c).balance;

        assert(
            balAfterDeposit == balBeforeDeposit + depositAmount &&
            userCreditNonNegative &&
            (
                withdrew
                    ? balAfterWithdraw == balBeforeWithdraw - userCreditBeforeWithdraw
                    : balAfterWithdraw == balBeforeWithdraw
            )
        );
    }
}

