contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amountA, uint256 amountB) public payable {
        require(amountA > 0, "amountA must be positive");
        require(amountB > 0, "amountB must be positive");

        // First, an unrelated account deposits amountB so B has positive credit.
        c.deposit{value: amountB}();

        // Account A deposits amountA.
        c.deposit{value: amountA}();

        // Record the contract balance after both deposits.
        uint256 balanceBeforeWithdraw = address(c).balance;

        // A withdraws all its credit. It should succeed.
        c.withdrawAll();

        // After successful withdrawal, the contract balance must have decreased by exactly amountA.
        assert(address(c).balance == balanceBeforeWithdraw - amountA);
    }

    receive() external payable {}
}

